"use client";
import {
  Card,
  CardContent,
  CardDescription,
  CardHeader,
  CardTitle,
} from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Badge } from "@/components/ui/badge";
import { Tabs, TabsContent, TabsList, TabsTrigger } from "@/components/ui/tabs";
import { AlertTriangle, Users, Eye } from "lucide-react";
import VisitorRequestForm from "@/components/form/visitor-request-form";
import { useEffect, useState } from "react";
import { GuardService } from "@/service/guardService";
import { getTime } from "@/lib/date-time";

type Status = "PENDING" | "APPROVED" | "DECLINED";
interface VisitRequestStatus {
  checkInTime: string;
  flatNo: string;
  id: number;
  name: string;
  purpose: string;
  relation: string;
  status: Status;
}

const SecurityDashboard = () => {
  const securityStats = [
    {
      title: "Current Alerts",
      value: "3",
      icon: AlertTriangle,
      description: "1 high priority",
      color: "text-red-600",
    },
    {
      title: "Visitors Today",
      value: "47",
      icon: Users,
      description: "12 pending",
      color: "text-blue-600",
    },
  ];

  const alerts = [
    {
      id: 1,
      type: "high",
      location: "Parking Garage Level 2",
      message: "Unauthorized access detected",
      time: "5 min ago",
      status: "active",
    },
    {
      id: 2,
      type: "medium",
      location: "Main Entrance",
      message: "Visitor without appointment",
      time: "15 min ago",
      status: "investigating",
    },
    {
      id: 3,
      type: "low",
      location: "Building A Lobby",
      message: "Camera offline",
      time: "1 hour ago",
      status: "resolved",
    },
  ];

  const [visitorRequests, setVisitorRequests] = useState<VisitRequestStatus[]>(
    [],
  );

  useEffect(() => {
    async function fetchVisitRequests() {
      const response = await GuardService.requestVisitStatus();
      setVisitorRequests(response.data);
    }

    fetchVisitRequests();
  }, []);

  function getVariant(status: Status) {
    switch (status.toLowerCase()) {
      case "APPROVED":
        return "default";
      case "PENDING":
        return "outline";
      case "DECLINED":
        return "destructive";
      default:
        return "default";
    }
  }

  function getColor(status: Status) {
    switch (status.toLowerCase()) {
      case "APPROVED":
        return "green";
      case "PENDING":
        return "yellow";
      case "DECLINED":
        return "red";
      default:
        return "gray";
    }
  }

  return (
    <div className="space-y-6 px-8 py-4">
      <div>
        <h1 className="text-3xl font-bold">Security Control Center</h1>
        <p className="text-muted-foreground">
          Monitor and manage building security operations
        </p>
      </div>

      {/* Security Stats */}
      <div className="grid gap-4 md:grid-cols-2 lg:grid-cols-4">
        {securityStats.map((stat, index) => (
          <Card key={index}>
            <CardHeader className="flex flex-row items-center justify-between space-y-0 pb-2">
              <CardTitle className="text-sm font-medium">
                {stat.title}
              </CardTitle>
              <stat.icon className={`h-4 w-4 ${stat.color}`} />
            </CardHeader>
            <CardContent>
              <div className="text-2xl font-bold">{stat.value}</div>
              <p className="text-xs text-muted-foreground">
                {stat.description}
              </p>
            </CardContent>
          </Card>
        ))}
      </div>

      <Tabs defaultValue="request" className="space-y-4">
        <TabsList>
          <TabsTrigger value="request">Request Visit</TabsTrigger>
          <TabsTrigger value="visitors">Visitor Requests</TabsTrigger>
          <TabsTrigger value="">Regular Visitors</TabsTrigger>
        </TabsList>

        <TabsContent value="request" className="space-y-4">
          <Card>
            <CardHeader>
              <CardTitle>Create Visitors Requests.</CardTitle>
              <CardDescription>Create a request</CardDescription>
            </CardHeader>
            <CardContent>
              <VisitorRequestForm />
            </CardContent>
          </Card>
          <Card>
            <CardHeader>
              <CardTitle>Visitor Requests Status</CardTitle>
              <CardDescription>Status of Visit Requests...</CardDescription>
            </CardHeader>
            <CardContent>
              <div className="space-y-4">
                {visitorRequests.map((request) => (
                  <div key={request.id} className="p-4 border rounded-lg">
                    <div className="flex items-center justify-between">
                      <div className="space-y-1">
                        <p className="font-medium">{request.name}</p>
                        <p className="text-sm text-muted-foreground">
                          Visiting {request.flatNo} • {request.purpose}
                        </p>
                        <p className="text-xs text-muted-foreground">
                          Scheduled: {getTime(request.checkInTime)}
                        </p>
                      </div>
                      <Badge
                        variant={getVariant(request.status)}
                        color={getColor(request.status)}
                      >
                        {request.status}
                      </Badge>
                    </div>
                  </div>
                ))}
              </div>
            </CardContent>
          </Card>
        </TabsContent>
        <TabsContent value="visitors" className="space-y-4">
          <Card>
            <CardHeader>
              <CardTitle>Visitor Requests from Resident</CardTitle>
              <CardDescription>All Visitor Requests...</CardDescription>
            </CardHeader>
            <CardContent>
              <div className="space-y-4">
                {visitorRequests.map((request) => (
                  <div key={request.id} className="p-4 border rounded-lg">
                    <div className="flex items-center justify-between">
                      <div className="space-y-1">
                        <p className="font-medium">{request.name}</p>
                        <p className="text-sm text-muted-foreground">
                          Visiting {request.flatNo} • {request.purpose}
                        </p>
                        <p className="text-xs text-muted-foreground">
                          Scheduled: {getTime(request.checkInTime)}
                        </p>
                      </div>
                    </div>
                  </div>
                ))}
              </div>
            </CardContent>
          </Card>
        </TabsContent>
      </Tabs>
    </div>
  );
};

export default SecurityDashboard;
